                      <Alert.Description>{failureReason}</Alert.Description>
                    </Alert.Content>
                  </Alert>
                ) : null}
              </div>
            </AlertDialog.Body>

            <AlertDialog.Footer>
              <Button onPress={() => setIsOpen(false)} variant="tertiary">
                キャンセル
              </Button>
              <Button onPress={handleConfirm} variant="danger">
                削除する
